export const cityInfo=p=>cities.find(c=>c.id===p?.city)||cities.find(c=>c.id==='perth');
export const currencies=['PHP','USD','SGD','AUD'];
export const currencyRates={AUD:1,PHP:38,USD:.66,SGD:.85};
export const regionDefaults={city:'perth',currency:'AUD',rate:1};
export function formatMoney(n,region=regionDefaults){return new Intl.NumberFormat('en',{style:'currency',currency:region.currency,currencyDisplay:'code',maximumFractionDigits:2}).format(n*region.rate);}
// Resolve a local wall time: earlier occurrence for overlaps; forward by the gap for missing times.
export function zonedTime(day,time,zone='Asia/Manila'){
 const target=Date.parse(day+'T'+time+':00Z');
 const formatter=new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'});
 const wall=ms=>{const v=Object.fromEntries(formatter.formatToParts(new Date(ms)).map(x=>[x.type,x.value]));return Date.parse(`${v.year}-${v.month}-${v.day}T${v.hour}:${v.minute}:${v.second}Z`);};
 const offsets=[...new Set([-36,0,36].map(h=>{const t=target+h*3600000;return wall(t)-t;}))];
 const candidates=offsets.map(offset=>target-offset).sort((a,b)=>a-b);
 const exact=candidates.filter(t=>wall(t)===target);
 if(exact.length)return new Date(exact[0]);
 const forward=candidates.filter(t=>wall(t)>target).sort((a,b)=>wall(a)-wall(b));
 return new Date(forward[0]);
}
export const defaults={city:'perth',trainingPlace:'home',timingMode:'suggested',goal:'consistency',experience:'beginner',minutes:35,workdays:[1,2,3,4,5],trainDays:[1,3,5],wake:'19:30',sleep:'13:00',offWake:'19:30',offSleep:'13:00',workStart:'22:00',workEnd:'09:00',prep:45,workout:'20:15',offWorkout:'20:15',meals:['19:45','01:00','09:30'],offMeals:['19:45','01:00','09:30'],equipment:[],bench:'none',barbell:false,weights:'',increment:1,limitations:[],otherLimit:'',nutrition:'habits',age:null,weight:null,height:null,sex:'',activity:1.4,budget:100,style:'economical',allergies:[],otherAllergy:'',avoid:'',diet:'any',pantry:{},prices:{},kitchen:['stove','fridge'],prepTime:45,journey:true,reminders:{workout:true,meals:[true,true,true]},quietStart:'12:00',quietEnd:'19:30'};
export function fresh(){return {version:VERSION,profile:null,plan:null,workouts:[],mealLogs:[],foodLogs:[],checkins:[],habits:{},journal:[],favorites:[],extraGroceries:[],review:[],calendarRevision:1,created:new Date().toISOString()};}
export const mins=t=>{const [h,m]=t.split(':').map(Number);return h*60+m;};
export const clock=m=>`${String(Math.floor(((m%1440)+1440)%1440/60)).padStart(2,'0')}:${String(((m%60)+60)%60).padStart(2,'0')}`;
export const addDays=(d,n)=>new Date(Date.parse(d+'T12:00:00Z')+n*86400000).toISOString().slice(0,10);
export const weekday=d=>new Date(d+'T12:00:00Z').getUTCDay();
export const localDate=(now,zone='Asia/Manila')=>new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).format(now);
export const settingsFor=(p,d)=>p.workdays.includes(weekday(d))?{wake:p.wake,sleep:p.sleep,workout:p.workout,meals:p.meals,work:true}:{wake:p.offWake,sleep:p.offSleep,workout:p.offWorkout,meals:p.offMeals,work:false};
export function wakingDay(p,now=new Date()){const zone=cityInfo(p).zone,today=localDate(now,zone);return now>=zonedTime(today,settingsFor(p,today).wake,zone)?today:addDays(today,-1);}
export function atTime(day,t,wake,zone='Asia/Manila'){return zonedTime(mins(t)<mins(wake)?addDays(day,1):day,t,zone).toISOString();}
export function inQuiet(t,p){const x=mins(t),a=mins(p.quietStart),b=mins(p.quietEnd);return a===b?false:a<b?x>=a&&x<b:x>=a||x<b;}
export function isAsleep(t,s){const x=mins(t),a=mins(s.sleep),b=mins(s.wake);return a===b?false:a<b?x>=a&&x<b:x>=a||x<b;}
export const recipe=id=>recipes.find(r=>r.id===id);
export function nutrition(r,servings=1,p=defaults){return Object.entries(r.items).reduce((a,[id,g])=>{const i=ingredients[id];a.kcal+=g*i.kcal/100*servings;a.protein+=g*i.protein/100*servings;a.cost+=g/(p.prices[id]?.pack||i.pack)*(p.prices[id]?.price??i.price)*servings;return a;},{kcal:0,protein:0,cost:0});}
export function allergyRules(p){
 const aliases={seafood:['fish','shellfish'],seafoods:['fish','shellfish'],egg:['egg'],eggs:['egg'],soy:['soy'],soya:['soy'],fish:['fish'],gluten:['gluten'],wheat:['gluten'],legume:['legume'],legumes:['legume'],milk:['milk'],dairy:['milk'],peanut:['peanut'],peanuts:['peanut'],'tree nut':['tree nut'],'tree nuts':['tree nut'],shellfish:['shellfish'],sesame:['sesame']};
 const terms=(p.otherAllergy||'').toLowerCase().split(/[,;\n]+/).map(x=>x.trim()).filter(Boolean),unknown=terms.filter(x=>!aliases[x]);
 return {allergens:[...new Set([...p.allergies,...terms.flatMap(x=>aliases[x]||[])])],unknown,recognized:terms.filter(x=>aliases[x])};
}
export function recipeEligibility(p){const rules=allergyRules(p),excluded=p.avoid.toLowerCase().split(',').map(x=>x.trim()).filter(Boolean);return recipes.map(r=>{const reasons=[];
 if(rules.unknown.length)reasons.push('Unrecognized allergy: '+rules.unknown.join(', '));
 const allergens=[...new Set(Object.keys(r.items).flatMap(id=>ingredients[id].allergens).filter(a=>rules.allergens.includes(a)))];if(allergens.length)reasons.push('Contains excluded ingredients: '+allergens.join(', '));
 const avoided=Object.keys(r.items).filter(id=>excluded.some(e=>ingredients[id].name.toLowerCase().includes(e)||id.includes(e)));if(avoided.length)reasons.push('Ingredients you avoid: '+avoided.map(id=>ingredients[id].name).join(', '));
 if(p.diet==='vegetarian'&&Object.keys(r.items).some(id=>['chicken','tuna','sardine'].includes(id)))reasons.push('Not vegetarian');
 if(r.time>p.prepTime)reasons.push('Needs '+r.time+' minutes; your limit is '+p.prepTime);
 const missing=r.gear.filter(g=>!p.kitchen.includes(g));if(missing.length)reasons.push('Needs equipment: '+missing.join(', '));
 return {recipe:r,reasons};});}
export function allowedRecipes(p){return recipeEligibility(p).filter(x=>!x.reasons.length).map(x=>x.recipe);}
export function availableExercises(p){const gym=p.trainingPlace==='gym',eq=gym?['dumbbell','bench','barbell','rack','cable','legpress']:[...p.equipment];if(!gym&&p.bench!=='none')eq.push('bench');return exercises.filter(e=>(gym||e.venue!=='gym')&&e.equipment.every(x=>eq.includes(x))&&!e.limits.some(x=>p.limitations.includes(x)));}
export function routine(p,short=false,history=[]){if((p.otherLimit||'').trim())return [];const available=availableExercises(p),patterns=(p.minutes<25||short)?['squat','hinge','push','pull']:['squat','hinge','push','pull','core'];const select=pattern=>{const matches=available.filter(e=>e.pattern===pattern);if(p.trainingPlace==='gym')return matches.find(e=>e.venue==='gym'&&e.gymPreferred)||matches.find(e=>e.venue==='gym')||matches.find(e=>e.gymPreferred)||matches[0];const weighted=matches.find(e=>e.equipment.length);if(weighted)return weighted;const levels=matches.filter(e=>Number.isFinite(e.level)).sort((a,b)=>a.level-b.level);let chosen=levels[0]||matches[0];for(const e of levels){const last=previousPerformance(history,e.id);if(last?.sets?.length&&last.sets.every(s=>s.reps>=e.reps[1]&&s.rpe<=8))chosen=levels.find(x=>x.level===e.level+1)||e;}return chosen;};const sets=short||p.minutes<30?2:p.goal==='build muscle'?4:p.experience==='beginner'||p.experience==='returning'?2:3;return patterns.map(select).filter(Boolean).map(e=>({...e,sets}));}
// Times are suggested for logistics, not a claim of physiologically optimal timing.
const offsetFrom=(time,wake)=>(mins(time)-mins(wake)+1440)%1440;
function chooseWorkout(p,s,preferred){
 const awake=offsetFrom(s.sleep,s.wake),start=offsetFrom(preferred,s.wake),cutoff=offsetFrom(p.workStart,s.wake)-p.prep;
 const free=s.work?Math.min(cutoff,awake)-start:awake-start;
 if(start<awake&&free>=p.minutes)return {time:preferred,duration:p.minutes,note:s.work?'Before your shift':'After waking · day off'};
 if(start<awake&&free>=15)return {time:preferred,duration:Math.min(p.minutes,Math.floor(free)),note:'Shorter session to fit your waking schedule'};
 if(s.work){const backup=['02:30',...Array.from({length:13},(_,i)=>clock(120+i*15))];for(const time of backup){const at=offsetFrom(time,s.wake);if(at+p.minutes<=awake&&mins(time)+p.minutes<=300)return {time,duration:p.minutes,note:'Backup window · the same session'};}}
 return null;
}
export function suggestTiming(p){
 function make(work){const s=work?{wake:p.wake,sleep:p.sleep,work:true}:{wake:p.offWake,sleep:p.offSleep,work:false};const awake=offsetFrom(s.sleep,s.wake),base=mins(s.wake),preferred=clock(base+(work?45:60)),workout=chooseWorkout(p,s,preferred);const clamp=x=>Math.max(1,Math.min(awake-1,Math.round(x/5)*5));
 let first=15,middle=awake/2,last=awake-120;
 if(work){const shiftStart=offsetFrom(p.workStart,s.wake),shiftEnd=offsetFrom(p.workEnd,s.wake),cutoff=shiftStart-p.prep;middle=(shiftStart+shiftEnd)/2;last=shiftEnd+30;if(workout&&offsetFrom(workout.time,s.wake)<shiftStart){const after=offsetFrom(workout.time,s.wake)+workout.duration+10;if(after+15<=cutoff)first=after;}}
 let times=[first,middle,last].map(clamp).sort((a,b)=>a-b);if(times[1]-times[0]<60||times[2]-times[1]<60)times=[.1,.5,.85].map(f=>clamp(awake*f));
 const reasons=[work?'Meals use your wake time, the middle of your shift, and the end of work. Work-break availability still needs your confirmation.':'Meals are spread across your day off, within your waking hours.',workout?workout.note+'. '+workout.duration+' minutes, with no second workout added.':'No suitable workout fits before work or in your backup window. Review your schedule or explicitly choose an after-work time.'];
 return {workout,meals:times.map(n=>clock(base+n)),reasons};}
 return {work:make(true),off:make(false)};
}
export function applySuggestedTiming(p){const suggestion=suggestTiming(p);return {...p,timingMode:'suggested',workout:suggestion.work.workout?.time||p.workout,offWorkout:suggestion.off.workout?.time||p.offWorkout,meals:suggestion.work.meals,offMeals:suggestion.off.meals};}
export function workoutTime(p,day){const s=settingsFor(p,day);return chooseWorkout(p,s,s.workout);}

export function energyEstimate(p){
 if(!Number.isFinite(Number(p.age))||p.age<18||p.age>100||!p.weight||p.weight<30||p.weight>300||!p.height||p.height<120||p.height>230||!['male','female'].includes(p.sex)||![1.2,1.4,1.6].includes(Number(p.activity)))return null;
 const resting=10*Number(p.weight)+6.25*Number(p.height)-5*Number(p.age)+(p.sex==='male'?5:-161);
 const tdee=Math.round(resting*Number(p.activity));
 return {resting:Math.round(resting),tdee,kcal:Math.round(tdee*(p.goal==='fat loss'?0.9:1)/50)*50,protein:Math.round(p.weight*1.6)};
}
export function targets(p){return p.nutrition==='habits'?null:energyEstimate(p);}

export function groceries(meals,p,extra=[]){const q={};for(const m of [...meals,...extra]){const r=recipe(m.recipe);if(!r)continue;for(const [id,g]of Object.entries(r.items))q[id]=(q[id]||0)+g*(m.servings||1);}return Object.entries(q).map(([id,g])=>{const i=ingredients[id],pack=p.prices[id]?.pack||i.pack,price=p.prices[id]?.price??i.price,need=Math.max(0,g-(p.pantry[id]||0));return {id,name:i.name,grams:g,need,pack,price,packages:Math.ceil(need/pack),purchase:Math.ceil(need/pack)*price,consumed:g/pack*price,pantry:Math.min(g,p.pantry[id]||0)};});}
export function buildPlan(p,start,old=null,history=[],favorites=[]){const allowed=allowedRecipes(p);const t=targets(p);let pool=[...allowed].sort((a,b)=>p.style==='convenience'?a.time-b.time:nutrition(a,1,p).cost-nutrition(b,1,p).cost);if(p.style==='balanced')pool=[...allowed];pool.sort((a,b)=>Object.keys(b.items).filter(x=>p.pantry[x]>0).length-Object.keys(a.items).filter(x=>p.pantry[x]>0).length);const days=Array.from({length:7},(_,i)=>{const day=addDays(start,i),s=settingsFor(p,day),w=workoutTime(p,day);return {day,work:s.work,scheduleWarning:p.trainDays.includes(weekday(day))&&!w?'No workout fits your waking hours. Review your schedule.':null,workout:p.trainDays.includes(weekday(day))&&w?{...w,id:`workout-${day}`,light:false}:null,meals:pool.length?s.meals.map((time,j)=>{const breakfast=['silog','oats','overnight'];const compatible=pool.filter(r=>j===0?breakfast.includes(r.id):!breakfast.includes(r.id));const base=compatible.length?compatible:pool;const preferred=base.filter(r=>favorites.includes(r.id));const slotPool=preferred.length?preferred:base;const chosen=slotPool[(Math.floor(i/2)+(j===2?1:0))%Math.min(slotPool.length,p.style==='economical'&&!preferred.length?3:slotPool.length)];const serving=t?Math.min(2.5,Math.max(0.5,Math.round(t.kcal/3/nutrition(chosen).kcal*4)/4)):1;return {id:`meal-${day}-${j}`,recipe:chosen.id,servings:serving,time};}):[]};});if(old)for(const d of days){const prev=old.days.find(x=>x.day===d.day);if(prev&&history.some(x=>x.day===d.day))d.workout=prev.workout;}return {start,days,created:new Date().toISOString(),targets:t};}
export function reschedule(plan,day,time){const out=structuredClone(plan);const d=out.days.find(x=>x.day===day);if(d?.workout){d.workout.time=time;d.workout.note='Your chosen time';}return out;}
export function swapMeal(plan,p,mealId,newRecipe){if(!allowedRecipes(p).some(r=>r.id===newRecipe))throw Error('This recipe does not match your food restrictions, kitchen, or preparation time.');const out=structuredClone(plan);const m=out.days.flatMap(d=>d.meals).find(x=>x.id===mealId);if(!m)throw Error('Meal not found.');m.recipe=newRecipe;return out;}
export function previousPerformance(history,exercise){return [...history].reverse().flatMap(w=>w.exercises||[]).find(e=>e.id===exercise);}
export function progression(history,exercise,p){const last=previousPerformance(history,exercise.id);if(!last?.sets?.length)return {weight:0,note:'Start light. Choose a weight that leaves 2–3 good reps in reserve.'};let load=Math.max(...last.sets.map(s=>s.weight));const expected=exercise.sets||last.plannedSets||routine(p).find(e=>e.id===exercise.id)?.sets||2;const top=last.formQuality==='controlled'&&last.sets.length>=expected&&last.sets.every(s=>s.reps>=exercise.reps[1]&&s.rpe<=8);const available=p.weights.split(',').map(Number).filter(n=>Number.isFinite(n)&&n>0).sort((a,b)=>a-b);const next=available.find(n=>n>=load+p.increment);if(top&&next&&exercise.unit!=='bodyweight')return {weight:next,note:`All planned sets reached the top of the range with reported controlled form at effort ≤8. Try ${next} kg if it feels controlled.`};return {weight:load,note:top?'Keep this load; no suitable heavier weight is listed. Add control or a rep.':last.formQuality==='broke-down'?'Reduce the load or range to regain control; stop any painful movement.':'Repeat a comfortable load. Complete all planned sets with controlled form before increasing.'};}
export function weeklyReview(state,end){const p=state.profile;if(state.review.some(r=>r.day>addDays(end,-7)&&r.day<=end))return {enough:false,title:'Review decision saved',text:'Your decision is saved. Keep logging; your next target review is available seven days after your last decision.',delta:null};const from=addDays(end,-13);const c=state.checkins.filter(x=>x.day>=from&&x.day<=end);const recent=c.filter(x=>x.day>addDays(end,-7)&&x.weight>0),prior=c.filter(x=>x.day<=addDays(end,-7)&&x.weight>0);const completeDays=new Set(state.foodLogs.filter(x=>x.complete&&x.day>=from&&x.day<=end).map(x=>x.day));const avg=a=>a.reduce((n,x)=>n+x.weight,0)/a.length;const enough=recent.length>=3&&prior.length>=3&&completeDays.size>=10&&c.filter(x=>x.hunger&&x.energy).length>=7;const t=state.plan?.targets;if(!enough||!t)return {enough:false,title:'Keep your targets steady',text:'A nutrition adjustment needs 3 weigh-ins in each of two weeks, 10 complete food days, and 7 hunger/energy check-ins over 14 days. Missing logs are unknown, never zero.',delta:null};const diff=avg(recent)-avg(prior),hungry=c.filter(x=>x.hunger>=4||x.energy<=2).length>=4;return {enough:true,title:hungry?'Consider a little more fuel':'Stay with your current plan',text:`Weekly mean weight changed ${diff>=0?'+':''}${diff.toFixed(2)} kg. ${hungry?'Frequent hunger or low energy suggests trying 100 kcal more daily.':'Continue another week; this app does not automatically cut calories.'}`,delta:hungry?100:null};}
export function reminders(state){const p=state.profile;if(!p||!state.plan)return [];const events=[];for(const d of state.plan.days){const s=settingsFor(p,d.day);if(d.workout&&p.reminders.workout&&!state.workouts.some(w=>w.day===d.day))events.push({id:d.workout.id,day:d.day,time:d.workout.time,title:'Afterhours Fitness · Training',duration:d.workout.duration});d.meals.forEach((m,i)=>{if(p.reminders.meals[i]&&!state.mealLogs.some(l=>l.id===m.id))events.push({id:m.id,day:d.day,time:m.time,title:'Afterhours Fitness · '+recipe(m.recipe).name,duration:20});});}return events.filter(e=>!inQuiet(e.time,p)&&!isAsleep(e.time,settingsFor(p,e.day))).map(e=>({...e,at:atTime(e.day,e.time,settingsFor(p,e.day).wake,cityInfo(p).zone)}));}
const icsDate=s=>new Date(s).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z/,'Z');
const icsEscape=s=>s.replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');
export function calendar(state){return ['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Afterhours//Night shift planner//EN','CALSCALE:GREGORIAN','METHOD:PUBLISH',...reminders(state).flatMap(e=>['BEGIN:VEVENT',`UID:${e.id}@afterhours.local`,`SEQUENCE:${state.calendarRevision}`,`DTSTAMP:${icsDate(new Date())}`,`DTSTART:${icsDate(e.at)}`,`DTEND:${icsDate(Date.parse(e.at)+e.duration*60000)}`,`SUMMARY:${icsEscape(e.title)}`,'DESCRIPTION:Day '+e.day+'. '+cityInfo(state.profile).zone+'.','BEGIN:VALARM','TRIGGER:-PT5M','ACTION:DISPLAY',`DESCRIPTION:${icsEscape(e.title)}`,'END:VALARM','END:VEVENT']),'END:VCALENDAR'].join('\r\n');}

export function scaledSteps(r,n){return r.steps.map(s=>s.replace(/(\d+(?:\.\d+)?) (ml|tbsp)\b/g,(_,amount,unit)=>`${+(Number(amount)*n).toFixed(1)} ${unit}`));}
export function household(id,g){const measures={rice:[180,'cup dry'],oats:[80,'cup'],egg:[50,'medium egg(s)'],chicken:[150,'small breast(s)'],tofu:[250,'block(s)'],mung:[200,'cup dry'],sardine:[155,'can(s)'],tuna:[120,'drained can(s)'],banana:[100,'medium banana(s)'],cabbage:[90,'cup shredded'],carrot:[60,'medium carrot(s)'],papaya:[140,'cup cubes'],tomato:[100,'medium tomato(es)'],onion:[70,'small onion(s)'],garlic:[3,'clove(s)'],ginger:[15,'thumb-size piece(s)'],oil:[5,'tsp'],vinegar:[15,'tbsp'],soy:[15,'tbsp']};const [unit,label]=measures[id];return `≈ ${+(g/unit).toFixed(2)} ${label}`;}

export function recipeText(r,n,p,region=regionDefaults){const total=nutrition(r,n,p),one=nutrition(r,1,p);return `${r.name}\nServings: ${n}\nPrep: ${r.prep} min · Cook: ${r.cook} min\n\nINGREDIENTS (raw edible weights unless labeled)\n`+Object.entries(r.items).map(([id,g])=>`${+(g*n).toFixed(1)} g ${ingredients[id].name}: ${household(id,g*n)}`).join('\n')+`\nWater: as directed; optional pinch of salt.\n\nMETHOD\n`+scaledSteps(r,n).map((s,i)=>`${i+1}. ${s}`).join('\n')+`\n\nSubstitutions: ${r.subs}\nStorage: ${r.storage}\n\nEstimated per serving: ${Math.round(one.kcal)} kcal · ${Math.round(one.protein)} g protein · ${formatMoney(one.cost,region)}\nEstimated total: ${Math.round(total.kcal)} kcal · ${Math.round(total.protein)} g protein · ${formatMoney(total.cost,region)}\nCosts are planning estimates; update local package prices in Settings.`;}
export function validateBackup(x){if(!x||typeof x!=='object'||x.version!==1)throw Error('Unsupported backup version. Use an Afterhours v1 backup.');if(x.region&&(!cities.some(c=>c.id===x.region.city)||!currencies.includes(x.region.currency)||!Number.isFinite(x.region.rate)||x.region.rate<=0||x.region.rate>10000))throw Error('Invalid location or currency.');if(x.profile?.city&&!cities.some(c=>c.id===x.profile.city))throw Error('Invalid city.');const arrays=['workouts','mealLogs','foodLogs','checkins','journal','favorites','extraGroceries','review'];for(const a of arrays)if(!Array.isArray(x[a])||x[a].length>50000)throw Error(`Invalid ${a} records.`);if(!x.habits||typeof x.habits!=='object'||Array.isArray(x.habits))throw Error('Invalid habit records.');const date=s=>typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&!isNaN(Date.parse(s));const number=(n,a,b)=>typeof n==='number'&&Number.isFinite(n)&&n>=a&&n<=b;const time=t=>typeof t==='string'&&/^([01]\d|2[0-3]):[0-5]\d$/.test(t);if(x.profile){const p=x.profile;p.trainingPlace||='home';p.timingMode||='manual';for(const [key,values] of Object.entries({goal:['consistency','fat loss','build muscle'],experience:['beginner','returning','experienced'],nutrition:['habits','estimates'],sex:['','female','male'],bench:['none','flat','adjustable'],style:['economical','balanced','convenience'],diet:['any','vegetarian']}))if(!values.includes(p[key]))throw Error('Invalid '+key);for(const [key,min,max]of [['age',18,100],['weight',30,300],['height',120,230]])if(p[key]!==null&&!number(p[key],min,max))throw Error('Invalid '+key);if(!number(p.activity,1,2.5)||!p.pantry||!p.prices||typeof p.journey!=='boolean')throw Error('Invalid profile.');for(const k of ['wake','sleep','offWake','offSleep','workout','offWorkout','quietStart','quietEnd','workStart','workEnd'])if(!time(p[k]))throw Error('Invalid schedule.');for(const k of ['meals','offMeals'])if(!Array.isArray(p[k])||p[k].length!==3||!p[k].every(time))throw Error('Invalid meal times.');for(const k of ['workdays','trainDays'])if(!Array.isArray(p[k])||!p[k].every(n=>number(n,0,6)))throw Error('Invalid weekdays.');for(const k of ['equipment','limitations','allergies','kitchen'])if(!Array.isArray(p[k])||!p[k].every(s=>typeof s==='string'))throw Error('Invalid preferences.');for(const k of ['weights','otherLimit','otherAllergy','avoid'])if(typeof p[k]!=='string')throw Error('Invalid text preference.');if(!number(p.minutes,15,90)||!number(p.increment,.25,20)||!number(p.budget,0,100000)||!number(p.prepTime,5,180)||!number(p.prep,0,180))throw Error('Invalid planning values.');if(!p.reminders||typeof p.reminders.workout!=='boolean'||!Array.isArray(p.reminders.meals)||p.reminders.meals.length!==3||!p.reminders.meals.every(v=>typeof v==='boolean'))throw Error('Invalid reminders.');for(const [id,g]of Object.entries(p.pantry||{}))if(!ingredients[id]||!number(g,0,100000))throw Error('Invalid pantry.');for(const [id,v]of Object.entries(p.prices||{}))if(!ingredients[id]||!number(v.price,0,100000)||!number(v.pack,1,100000))throw Error('Invalid prices.');}
for(const [d,h] of Object.entries(x.habits))if(!date(d)||!h||typeof h!=='object'||Object.keys(h).some(k=>!['water','sleep','recovery'].includes(k))||Object.values(h).some(v=>typeof v!=='boolean'))throw Error('Invalid habit record.');for(const r of x.review)if(!date(r.day)||typeof r.decision!=='string')throw Error('Invalid review.');if(x.plan){if(x.plan.targets&&(!number(x.plan.targets.kcal,500,10000)||!number(x.plan.targets.protein,0,1000)))throw Error('Invalid nutrition targets.');if(!x.profile||!date(x.plan.start)||!Array.isArray(x.plan.days)||x.plan.days.length!==7)throw Error('Invalid plan.');for(const d of x.plan.days){if(!date(d.day)||!Array.isArray(d.meals)||d.meals.length>3)throw Error('Invalid planned day.');for(const m of d.meals)if(!recipe(m.recipe)||!number(m.servings,.25,10)||!time(m.time)||typeof m.id!=='string')throw Error('Invalid planned meal.');if(d.workout&&(!time(d.workout.time)||!number(d.workout.duration,15,90)||typeof d.workout.id!=='string'))throw Error('Invalid workout.');}}
for(const w of x.workouts){if(!date(w.day)||!Array.isArray(w.exercises))throw Error('Invalid workout history.');for(const e of w.exercises)if(!exercises.some(a=>a.id===e.id)||!Array.isArray(e.sets)||(e.formQuality!==undefined&&!['','controlled','uncertain','broke-down'].includes(e.formQuality))||(e.plannedSets!==undefined&&!number(e.plannedSets,1,20))||!e.sets.every(s=>number(s.reps,1,100)&&number(s.weight,0,500)&&number(s.rpe,1,10)))throw Error('Invalid exercise log.');}for(const c of x.checkins)if(!date(c.day)||(c.weight!==null&&!number(c.weight,20,400))||!number(c.hunger,1,5)||!number(c.energy,1,5))throw Error('Invalid check-in.');for(const m of x.mealLogs)if(typeof m.id!=='string'||!date(m.day)||!recipe(m.recipe)||!number(m.servings,.25,10))throw Error('Invalid meal log.');for(const f of x.foodLogs)if(!date(f.day)||!number(f.kcal,0,20000)||!number(f.protein,0,1000)||typeof f.complete!=='boolean')throw Error('Invalid food log.');for(const j of x.journal)if(!date(j.day)||typeof j.text!=='string'||j.text.length>10000)throw Error('Invalid journal.');for(const f of x.favorites)if(!recipe(f))throw Error('Invalid favorite.');for(const m of x.extraGroceries)if(!recipe(m.recipe)||!number(m.servings,.25,10))throw Error('Invalid grocery addition.');if(!number(x.calendarRevision,1,1000000))throw Error('Invalid calendar revision.');return x;}

// Derived from unique saved activities: toggles and duplicate imports cannot farm XP.
export const rankLadder=[...['Iron','Bronze','Silver','Gold','Platinum','Emerald','Diamond'].flatMap(t=>['IV','III','II','I'].map(d=>t+' '+d)),'Master','Grandmaster','Challenger'];
export function journey(s){
 const movements=new Map(), sessions=new Set(), meals=new Set(), recovery=new Set();
 for(const w of s.workouts)for(const e of w.exercises)if(e.sets?.length){movements.set(w.day+':'+e.id,e);sessions.add(w.day);}
 for(const m of s.mealLogs)meals.add(m.id);
 let habitCount=0;for(const [d,h]of Object.entries(s.habits)){habitCount+=['water','sleep','recovery'].filter(k=>h[k]===true).length;if(h.recovery)recovery.add(d);}
 const xp=movements.size*20+sessions.size*30+meals.size*10+habitCount*10;
 const index=Math.min(rankLadder.length-1,Math.floor(xp/250)), next=rankLadder[index+1]||null;
 const controlled=[...movements.values()].filter(e=>e.formQuality==='controlled').length;
 const achievements=[['first','First step','Save one exercise',movements.size,1],['session','Session starter','Save one training session',sessions.size,1],['ten','Finding your rhythm','Save 10 exercises across your sessions',movements.size,10],['form','Control comes first','Report controlled technique for 5 exercises',controlled,5],['fuel','Fuel the routine','Log 10 planned meals',meals.size,10],['recovery','Recovery counts','Log recovery on 3 days',recovery.size,3],['consistent','Showing up','Save training on 12 days',sessions.size,12],['century','One hundred movements','Save 100 exercises',movements.size,100]].map(([id,name,rule,value,target])=>({id,name,rule,value,target,unlocked:value>=target}));
 return {xp,index,rank:rankLadder[index],next,remaining:next?(index+1)*250-xp:0,percent:next?(xp%250)/250*100:100,achievements,movements:movements.size,sessions:sessions.size};
}

export function recommendMeals(p,favorites=[]){const allowed=allowedRecipes(p);const chosen=allowed.filter(r=>favorites.includes(r.id));return {recipes:chosen.length?chosen:allowed.slice(0,3),chosen:chosen.length>0,blocked:favorites.filter(id=>!allowed.some(r=>r.id===id))};}
export function refreshMeals(plan,p,favorites,logs=[],from=wakingDay(p)){
 const out=structuredClone(plan),suggested=buildPlan(p,plan.start,null,[],favorites),logged=new Set(logs.map(l=>l.id));
 for(const d of out.days){if(d.day<from)continue;const next=suggested.days.find(x=>x.day===d.day);d.meals=d.meals.length?d.meals.map((m,i)=>{if(logged.has(m.id))return m;const n=next.meals[i];return n?{...n,id:m.id,time:m.time}:null;}).filter(Boolean):next.meals;}
 return out;
}
